CREATE DATABASE IF NOT EXISTS interview_shop;
USE interview_shop;
CREATE TABLE customers (
 id INT PRIMARY KEY, name VARCHAR(100) NOT NULL,
 city VARCHAR(100), email VARCHAR(255) UNIQUE
) ENGINE=InnoDB;
CREATE TABLE products (
 id INT PRIMARY KEY, name VARCHAR(100) NOT NULL,
 price DECIMAL(10,2) NOT NULL CHECK(price>=0)
) ENGINE=InnoDB;
CREATE TABLE orders (
 id INT PRIMARY KEY, customer_id INT,
 total DECIMAL(10,2) NOT NULL, created_at DATE NOT NULL,
 FOREIGN KEY (customer_id) REFERENCES customers(id)
) ENGINE=InnoDB;
